import { loadFont } from "@remotion/google-fonts/Fredoka";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// TERAPIA SOCIAL (Marcos terapia) · pedido de 10/11/2026 pelo grupo de vendas. Terapia online em que a pessoa escolhe quanto
// paga pela sessão. Copy do cliente gravada como veio (voz o locutor). Destaque pedido: "VOCÊ ESCOLHE O VALOR DA SUA TERAPIA"
// ocupando a tela inteira. Identidade: vermelho do logo (#F61803), branco, letra arredondada e o sorriso do logo, que é o
// fio do vídeo (desenha embaixo de TERAPIA, vira a inundação branca, sublinha o destaque e volta no logo final).
// Jeito: motion (só o logo veio).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const MA_FPS = 30;
export const MA_FRAMES = Math.round(26.0 * MA_FPS);

// v2: pausas da voz cortadas para 0,45 s (revisão do diretor). Os tempos do código continuam os da v1;
// esta tabela converte o tempo novo (do vídeo) no antigo, pelas palavras (edit/mapa-v2.json).
const MAP_NEW = [0.0, 2.304, 2.754, 4.797, 5.378, 6.82, 7.27, 10.615, 11.065, 15.551, 16.013, 18.636, 19.128, 29.128];
const MAP_OLD = [0.0, 2.304, 2.954, 4.997, 5.647, 7.089, 7.739, 11.084, 11.644, 16.13, 16.78, 19.403, 20.053, 30.053];

const RED = "#F61803";
const DEEP = "#C81202";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN = Easing.bezier(0.7, 0, 0.84, 0);
const IO = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const ki = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
const kio = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IO });
const sp = (t: number, a: number, damping = 18, stiffness = 120) =>
  spring({ frame: Math.max(0, Math.round((t - a) * MA_FPS)), fps: MA_FPS, config: { damping, stiffness } });
const img = (n: string) => staticFile(`marcos/${n}`);
const on = (t: number, a: number, b: number) => t >= a && t < b;
const toOld = (tn: number) => interpolate(tn, MAP_NEW, MAP_OLD, cl);

// tempos das cenas (s), tirados de edit/palavras.json (voz cortada, começa em 0,35 s)
const T = { s2: 2.05, s3: 5.3, s4: 7.42, s5: 11.3, s6: 12.5, s7: 16.42, s8: 19.72, s9: 23.55 };

// ───────── peças ─────────
const Bg: React.FC<{ c: string; glow?: string }> = ({ c, glow }) => {
  const s = useCurrentFrame() / MA_FPS;
  const x = 50 + 12 * Math.sin(s * 0.8);
  const y = 46 + 8 * Math.cos(s * 0.6);
  return <AbsoluteFill style={{ background: glow ? `radial-gradient(ellipse 80% 55% at ${x}% ${y}%, ${glow} 0%, ${c} 70%)` : c }} />;
};

// texto que sobe com opacidade (y +30 px, 8 quadros); invisível até a vez dele
const Rise: React.FC<{ t: number; at: number; children: React.ReactNode; d?: number }> = ({ t, at, children, d = 0.27 }) => {
  const q = k(t, at, d);
  return <div style={{ lineHeight: 1.0, opacity: t < at ? 0 : q, transform: `translateY(${(1 - q) * 30}px)` }}>{children}</div>;
};

// linha que abre espaço no bloco quando entra (o bloco se recentraliza, sem buraco reservado)
const Grow: React.FC<{ t: number; at: number; h: number; children: React.ReactNode }> = ({ t, at, h, children }) => {
  const g = kio(t, at, 0.25);
  return (
    <div style={{ height: g * h, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "flex-end" }}>
      <Rise t={t} at={at + 0.2}>{children}</Rise>
    </div>
  );
};

// fundo das cenas brancas: formas da marca em vermelho bem claro, andando devagar
const Shapes: React.FC = () => {
  const s = useCurrentFrame() / MA_FPS;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <div style={{ position: "absolute", width: 760, height: 760, borderRadius: 380, background: "#FFEFEC", left: -260 + 40 * Math.sin(s * 0.35), top: 120 + 50 * Math.cos(s * 0.3) }} />
      <div style={{ position: "absolute", width: 620, height: 620, borderRadius: 310, background: "#FFF2EF", right: -240 + 40 * Math.cos(s * 0.4), top: 1180 + 40 * Math.sin(s * 0.33) }} />
      <svg width="1300" height="400" style={{ position: "absolute", left: -110 + 30 * Math.sin(s * 0.25), top: 1500 }}>
        <path d="M 60 40 Q 650 520 1240 40" fill="none" stroke="#FFE6E1" strokeWidth="70" strokeLinecap="round" />
      </svg>
    </AbsoluteFill>
  );
};

// palavra que bate na tela: entra grande e assenta (mola com pouco overshoot)
const Slam: React.FC<{ t: number; at: number; children: React.ReactNode }> = ({ t, at, children }) => {
  const s = sp(t, at, 15, 190);
  const v = Math.abs(sp(t, at + 1 / MA_FPS, 15, 190) - s) * MA_FPS;
  return (
    <div style={{ opacity: t < at ? 0 : Math.min(1, s * 3), transform: `scale(${1.18 - 0.18 * s})`, filter: `blur(${Math.min(6, v * 0.8)}px)` }}>{children}</div>
  );
};

// o sorriso do logo, desenhado
const Smile: React.FC<{ t: number; at: number; w: number; color?: string; stroke?: number; d?: number }> = ({ t, at, w, color = WHITE, stroke = 26, d = 0.5 }) => {
  const h = w * 0.2;
  const len = w * 1.12;
  const q = k(t, at, d);
  return (
    <svg width={w + stroke} height={h + stroke} style={{ overflow: "visible", display: "block" }}>
      <path d={`M ${stroke / 2} ${stroke / 2} Q ${w / 2 + stroke / 2} ${h * 2 + stroke / 2} ${w + stroke / 2} ${stroke / 2}`} fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round"
        strokeDasharray={len} strokeDashoffset={len * (1 - q)} opacity={t < at ? 0 : 1} />
    </svg>
  );
};

const Col: React.FC<{ children: React.ReactNode; top?: number; bottom?: number; gap?: number; style?: React.CSSProperties }> = ({ children, top = 250, bottom = 440, gap = 0, style }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, bottom, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap, textAlign: "center", ...style }}>{children}</div>
);

const txt = (size: number, color: string, weight = 700): React.CSSProperties => ({ fontFamily: F, fontWeight: weight, fontSize: size, color, whiteSpace: "nowrap", letterSpacing: "-0.005em", lineHeight: 1 });

// ───────── cena 1 · gancho (vermelho): a dor grande já no primeiro quadro, em batidas ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1 + 0.03 * k(t, 0.3, 1.8);
  return (
    <AbsoluteFill>
      <Bg c={RED} glow="#FF3A1E" />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <Col gap={14}>
          <Slam t={t} at={0}><div style={txt(72, WHITE, 600)}>Você sente que</div></Slam>
          <Slam t={t} at={0.12}><div style={txt(116, WHITE, 700)}>PRECISA DE</div></Slam>
          <Slam t={t} at={0.26}><div style={txt(150, WHITE, 700)}>TERAPIA?</div></Slam>
          <div style={{ marginTop: 10 }}><Smile t={t} at={0.6} w={440} stroke={30} /></div>
        </Col>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · problema (branco): o cartão TERAPIA aparece inteiro e não cabe na carteira ─────────
const Wallet: React.FC<{ t: number; at: number; hit: number }> = ({ t, at, hit }) => {
  const s = sp(t, at, 16, 140);
  // cartão inteiro em cima; em "cabe" desce, bate na boca da carteira e volta: não cabe
  const drop = sp(t, hit, 11, 160);
  const back = sp(t, hit + 0.35, 14, 150);
  const cardY = drop * 110 - back * 60;
  const tilt = drop * -3 + back * 5;
  return (
    <div style={{ position: "relative", width: 620, height: 640, opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 80}px)` }}>
      <div style={{ position: "absolute", left: 40, top: cardY, width: 540, height: 300, borderRadius: 34, background: WHITE, border: `12px solid ${RED}`, boxSizing: "border-box",
        transform: `rotate(${tilt}deg)`, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 18px 40px rgba(160,20,0,0.18)" }}>
        <Img src={img("marca-vermelho.png")} style={{ width: 340 }} />
      </div>
      <div style={{ position: "absolute", left: 90, right: 90, top: 330, height: 300, borderRadius: 46, background: RED, boxShadow: "0 26px 50px rgba(160,20,0,0.25)" }}>
        <div style={{ position: "absolute", right: -26, top: 104, width: 150, height: 96, borderRadius: 30, background: DEEP, border: `10px solid ${RED}`, boxSizing: "content-box" }} />
        <div style={{ position: "absolute", right: 28, top: 140, width: 34, height: 34, borderRadius: 17, background: WHITE }} />
      </div>
    </div>
  );
};

const S2: React.FC<{ t: number }> = ({ t }) => {
  const a = T.s2;
  const cam = 1 + 0.02 * k(t, a, 3.2);
  return (
    <AbsoluteFill>
      <Bg c={WHITE} />
      <Shapes />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <Col gap={0}>
          <Rise t={t} at={2.4}><div style={txt(60, RED, 600)}>mas acha que</div></Rise>
          <div style={{ height: 8 }} />
          <Rise t={t} at={3.0}><div style={txt(60, RED, 600)}>não cabe no seu</div></Rise>
          <Grow t={t} at={3.85} h={146}><div style={txt(116, RED, 700)}>ORÇAMENTO?</div></Grow>
          <div style={{ height: 40 }} />
          <div style={{ zoom: 1.1 }}><Wallet t={t} at={2.1} hit={3.8} /></div>
        </Col>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · a marca (vermelho sobe de baixo e vira o fundo) ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const s = sp(t, 6.1, 15, 150);
  const cam = (1.06 - 0.06 * k(t, T.s3, 2.0)) * (1 + 7 * ki(t, T.s4 - 0.05, 0.45));
  return (
    <AbsoluteFill>
      <Bg c={RED} glow="#FF3A1E" />
      <AbsoluteFill style={{ transform: `scale(${cam})`, transformOrigin: "52.6% 52.3%" }}>
        <Col gap={46}>
          <Rise t={t} at={5.6}><div style={txt(96, WHITE, 600)}>Conheça o</div></Rise>
          <div style={{ opacity: Math.min(1, s * 3), transform: `scale(${0.55 + 0.45 * s}) rotate(${(1 - s) * -6}deg)` }}>
            <Img src={img("logo-branco.png")} style={{ width: 700, display: "block" }} />
          </div>
        </Col>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 4 · os três pontos, um por vez no mesmo lugar ─────────
const IconPhone = () => (
  <svg width="170" height="170" viewBox="0 0 100 100">
    <rect x="26" y="8" width="48" height="84" rx="10" fill="none" stroke={WHITE} strokeWidth="7" />
    <rect x="35" y="36" width="20" height="16" rx="3" fill={WHITE} />
    <path d="M57 40 L66 35 L66 53 L57 48 Z" fill={WHITE} />
    <circle cx="50" cy="80" r="4" fill={WHITE} />
  </svg>
);
const IconHeart = () => (
  <svg width="180" height="180" viewBox="0 0 100 100">
    <path d="M50 86 C18 64 8 46 14 30 C20 14 42 12 50 28 C58 12 80 14 86 30 C92 46 82 64 50 86 Z" fill={WHITE} />
  </svg>
);
const IconCoin = () => (
  <svg width="180" height="180" viewBox="0 0 100 100">
    <circle cx="50" cy="50" r="38" fill="none" stroke={WHITE} strokeWidth="8" />
    <text x="50" y="62" textAnchor="middle" fontFamily={F} fontWeight={700} fontSize="34" fill={WHITE}>R$</text>
  </svg>
);

const Item: React.FC<{ t: number; at: number; until: number; icon: React.ReactNode; lines: string[]; size: number; disc: number }> = ({ t, at, until, icon, lines, size, disc }) => {
  if (t < at - 0.05 || t >= until) return null;
  const s = sp(t, at, 16, 160);
  return (
    <Col gap={50} style={{ opacity: Math.min(1, s * 3), transform: `scale(${(0.85 + 0.15 * s) * (1 + 0.05 * kio(t, at + 0.4, 1.2))})` }}>
      <div style={{ width: disc, height: disc, borderRadius: disc / 2, background: RED, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${0.4 + 0.6 * sp(t, at + 0.05, 13, 200)}) rotateY(${kio(t, at + 1.0, 0.5) * 360}deg)`, boxShadow: "0 30px 60px rgba(200,20,0,0.22)" }}><div style={{ transform: `scale(${disc / 270})`, display: "flex" }}>{icon}</div></div>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
        {lines.map((l, i) => <Rise key={i} t={t} at={at + i * 0.08}><div style={txt(i === 0 ? 100 : size, RED, 700)}>{l}</div></Rise>)}
        <div style={{ marginTop: 6 }}><Smile t={t} at={at + 0.55} w={420} color={RED} stroke={24} d={0.45} /></div>
      </div>
    </Col>
  );
};

const S4: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1 + 0.04 * k(t, T.s4, 3.8);
  const ia = sp(t, 7.7, 14, 180), ib = sp(t, 8.84, 14, 180);
  const outA = ki(t, 9.74, 0.12);
  const disc = (q: number, icon: React.ReactNode) => (
    <div style={{ width: 260, height: 260, borderRadius: 130, background: RED, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${q})`, boxShadow: "0 24px 50px rgba(200,20,0,0.2)" }}>
      <div style={{ transform: "scale(0.95)", display: "flex" }}>{icon}</div>
    </div>
  );
  return (
    <AbsoluteFill>
      <Bg c={WHITE} />
      <Shapes />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        {t < 9.86 && (
          <Col gap={44} style={{ opacity: 1 - outA, transform: `scale(${1 - outA * 0.08})` }}>
            <div style={{ display: "flex" }}>{disc(ia, <IconPhone />)}<div style={{ width: kio(t, 8.7, 0.25) * 310, display: "flex", justifyContent: "flex-end" }}>{t >= 8.84 && disc(ib, <IconHeart />)}</div></div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
              <Rise t={t} at={7.72}><div style={txt(108, RED, 700)}>ATENDIMENTO</div></Rise>
              <Rise t={t} at={8.2}><div style={txt(196, RED, 700)}>ONLINE</div></Rise>
            </div>
            <Rise t={t} at={8.84}><div style={txt(94, RED, 600)}>com acolhimento</div></Rise>
          </Col>
        )}
        <Item t={t} at={9.86} until={99} icon={<IconCoin />} lines={["valores", "ACESSÍVEIS"]} size={112} disc={500} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 5 · "e o melhor" ─────────
const S5: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Bg c={WHITE} />
    <Shapes />
    <Col gap={24}>
      <Slam t={t} at={11.6}><div style={{ ...txt(210, RED, 700), lineHeight: 0.95, textAlign: "center" }}>E o<br />melhor:</div></Slam>
      <div style={{ opacity: k(t, 11.9, 0.3) }}><Smile t={t} at={11.9} w={440} color={RED} stroke={32} d={0.4} /></div>
    </Col>
  </AbsoluteFill>
);

// ───────── cena 6 · o destaque em tela cheia: VOCÊ ESCOLHE O VALOR DA SUA TERAPIA ─────────
const S6: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1 + 0.025 * k(t, 13.3, 3.2);
  const pill = sp(t, 14.38, 14, 170);
  return (
    <AbsoluteFill>
      <Bg c={DEEP} glow={RED} />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <Col gap={0} top={300} bottom={480}>
          <Slam t={t} at={13.36}><div style={{ ...txt(98, WHITE, 700), wordSpacing: "0.2em" }}>VOCÊ ESCOLHE</div></Slam>
          <div style={{ height: 26 }} />
          <Slam t={t} at={14.38}>
            <div style={{ background: WHITE, borderRadius: 90, padding: "24px 50px 30px", display: "flex", flexDirection: "column", alignItems: "center", transform: `rotate(${(1 - pill) * -4 - 1.5}deg)` }}>
              <div style={txt(150, RED, 700)}>QUANTO</div>
              <Grow t={t} at={14.8} h={158}><div style={txt(150, RED, 700)}>PAGAR</div></Grow>
            </div>
          </Slam>
          <Grow t={t} at={15.52} h={126}><div style={{ ...txt(100, WHITE, 700), wordSpacing: "0.2em" }}>POR SESSÃO</div></Grow>
          <div style={{ height: kio(t, 15.85, 0.25) * 96, overflow: "hidden", display: "flex", alignItems: "flex-start", paddingTop: 6 }}><Smile t={t} at={16.05} w={380} stroke={28} /></div>
        </Col>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 7 · cuidar de você: "ACESSÍVEL" é o título ─────────
const S7: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1.03 - 0.03 * kio(t, T.s7, 3.3);
  const hs = sp(t, 16.75, 12, 170);
  const pulse = (a: number) => interpolate(t, [a, a + 0.08, a + 0.3], [0, 1, 0], cl);
  const beat = 1 + 0.16 * pulse(17.25) + 0.12 * pulse(17.55) + 0.16 * pulse(18.4) + 0.12 * pulse(18.7);
  const pill = spring({ frame: Math.max(0, Math.round((t - 18.3) * MA_FPS)), fps: MA_FPS, config: { damping: 20, stiffness: 160 } });
  return (
    <AbsoluteFill>
      <Bg c={WHITE} />
      <Shapes />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <Col gap={0}>
          <div style={{ transform: `scale(${(0.3 + 0.7 * hs) * beat})`, opacity: Math.min(1, hs * 3), marginBottom: 40 }}>
            <svg width="290" height="261" viewBox="0 0 100 90"><path d="M50 84 C18 62 6 44 12 27 C18 11 41 9 50 25 C59 9 82 11 88 27 C94 44 82 62 50 84 Z" fill={RED} /></svg>
          </div>
          <Rise t={t} at={16.74}><div style={txt(94, RED, 700)}>Cuidar de você</div></Rise>
          <Grow t={t} at={17.26} h={112}><div style={txt(94, RED, 700)}>pode ser mais</div></Grow>
          <div style={{ height: kio(t, 18.02, 0.25) * 230, display: "flex", alignItems: "flex-end" }}>
            <div style={{ opacity: t < 18.3 ? 0 : k(t, 18.3, 0.12), transform: `scale(${0.8 + 0.2 * pill})` }}>
              <div style={{ ...txt(124, WHITE, 700), background: RED, borderRadius: 100, padding: "26px 36px 34px" }}>ACESSÍVEL</div>
            </div>
          </div>
        </Col>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 8 · chamada: o botão troca de texto a cada passo e o cursor clica ─────────
const Cursor: React.FC<{ t: number; taps: number[] }> = ({ t, taps }) => {
  const enter = sp(t, 19.9, 16, 110);
  let press = 0;
  for (const a of taps) press = Math.max(press, interpolate(t, [a - 0.06, a, a + 0.14], [0, 1, 0], cl));
  return (
    <div style={{ position: "absolute", left: 836 + (1 - enter) * 260, top: 1060 + (1 - enter) * 300, transform: `scale(${1 - press * 0.14})`, transformOrigin: "10% 10%" }}>
      <svg width="90" height="106" viewBox="0 0 22 26"><path d="M2 2 L2 21 L7 16.5 L10.5 24 L14 22.5 L10.6 15.2 L17.5 15 Z" fill={WHITE} stroke={DEEP} strokeWidth="1.6" strokeLinejoin="round" /></svg>
    </div>
  );
};

const S8: React.FC<{ t: number }> = ({ t }) => {
  const steps = [
    { at: 20.0, text: "Clique no link" },
    { at: 20.94, text: "Faça seu cadastro" },
    { at: 22.2, text: "Agende sua terapia" },
  ];
  const btn = sp(t, 20.0, 15, 150);
  const logo = sp(t, 19.9, 15, 140);
  const cam = 1.12 - 0.12 * kio(t, T.s8, 3.9);
  const cur = steps.reduce((acc, s, i) => (t >= s.at - 0.05 ? i : acc), 0);
  const sheen = ((t - 23.6) % 1.6) / 1.6;
  return (
    <AbsoluteFill>
      <Bg c={RED} glow="#FF3A1E" />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        {/* logo assina em cima a partir de "terapia" */}
        <div style={{ position: "absolute", left: 0, right: 0, top: 400, display: "flex", justifyContent: "center", opacity: Math.min(1, logo * 3), transform: `translateY(${(1 - logo) * -60}px) scale(${0.8 + 0.2 * logo})` }}>
          <Img src={img("logo-branco.png")} style={{ width: 700 }} />
        </div>
        {/* passos 1·2·3 */}
        <div style={{ position: "absolute", left: 0, right: 0, top: 1200, display: "flex", justifyContent: "center", gap: 40 }}>
          {steps.map((s, i) => {
            const q = sp(t, s.at, 14, 180);
            return <div key={i} style={{ ...txt(78, i <= cur && t >= s.at ? RED : WHITE, 700), width: 132, height: 132, borderRadius: 66, display: "flex", alignItems: "center", justifyContent: "center",
              background: t >= s.at ? WHITE : "rgba(255,255,255,0.18)", transform: `scale(${t >= s.at ? 0.8 + 0.2 * q : 0.8})`, opacity: k(t, 20.0 + i * 0.08, 0.3) }}>{i + 1}</div>;
          })}
        </div>
      </AbsoluteFill>
      {/* botão fora da câmera: fica parado e no mesmo lugar */}
      <div style={{ position: "absolute", left: 160, right: 160, top: 930, height: 196, opacity: Math.min(1, btn * 3), transform: `scale(${0.7 + 0.3 * btn})` }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 98, background: WHITE, overflow: "hidden", boxShadow: "0 24px 50px rgba(120,10,0,0.35)" }}>
          {t > 23.6 && <div style={{ position: "absolute", top: 0, bottom: 0, width: 160, left: -200 + sheen * 1100, background: "linear-gradient(90deg, rgba(246,24,3,0), rgba(246,24,3,0.12), rgba(246,24,3,0))", transform: "skewX(-20deg)" }} />}
          {steps.map((s, i) => {
            const nxt = steps[i + 1];
            if (t < s.at - 0.05 || (nxt && t >= nxt.at)) return null;
            const q = k(t, s.at, 0.32);
            const o = nxt ? ki(t, nxt.at - 0.14, 0.14) : 0;
            return <div key={i} style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", ...txt(66, RED, 700), opacity: q * (1 - o), transform: `scale(${0.85 + 0.15 * q})` }}>{s.text}</div>;
          })}
        </div>
      </div>
      <Cursor t={t} taps={[20.0, 20.94, 22.2]} />
    </AbsoluteFill>
  );
};

// ───────── cena 9 · cartão final (branco): o botão cresce e vira o fundo; logo vermelho e a chamada ─────────
const S9: React.FC<{ t: number }> = ({ t }) => {
  // nasce do botão vermelho por inundação: o logo fica no mesmo lugar; no lugar do botão, uma chamada única e grande
  const a = T.s9;
  const cam = 1.0 + 0.04 * kio(t, a + 0.4, 4.0);
  const cta = sp(t, a + 0.2, 16, 150);
  const press = interpolate(t, [24.75, 24.82, 25.0], [0, 1, 0], cl);
  const press2 = interpolate(t, [25.85, 25.92, 26.1], [0, 1, 0], cl);
  return (
    <AbsoluteFill>
      <Bg c={WHITE} />
      <Shapes />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 400, display: "flex", justifyContent: "center" }}>
          <Img src={img("logo-vermelho.png")} style={{ width: 700 }} />
        </div>
        <div style={{ position: "absolute", left: 170, right: 170, top: 920, display: "flex", justifyContent: "center", transform: `scale(${(0.85 + 0.15 * cta) * (1 - 0.04 * (press + press2))})` }}>
          <div style={{ background: RED, borderRadius: 70, padding: "34px 40px 42px", display: "flex", flexDirection: "column", alignItems: "center", gap: 10, boxShadow: "0 24px 50px rgba(200,20,0,0.25)" }}>
            <div style={txt(76, WHITE, 700)}>Clique no link</div>
            <div style={txt(76, WHITE, 700)}>abaixo e agende</div>
          </div>
        </div>
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 826, top: 1160, transform: `scale(${1 - 0.14 * (press + press2)})`, transformOrigin: "10% 10%", opacity: k(t, a + 0.5, 0.3) }}>
        <svg width="90" height="106" viewBox="0 0 22 26"><path d="M2 2 L2 21 L7 16.5 L10.5 24 L14 22.5 L10.6 15.2 L17.5 15 Z" fill={WHITE} stroke={DEEP} strokeWidth="1.6" strokeLinejoin="round" /></svg>
      </div>
    </AbsoluteFill>
  );
};

// ───────── transições (uma diferente em cada troca) ─────────
// 1→2: o sorriso abre e o branco inunda a partir dele
const Flood: React.FC<{ t: number; at: number; d: number; x: number; y: number; children: React.ReactNode }> = ({ t, at, d, x, y, children }) => (
  <AbsoluteFill style={{ clipPath: `circle(${kio(t, at, d) * 150}% at ${x}% ${y}%)` }}>{children}</AbsoluteFill>
);
// 2→3: o vermelho sobe de baixo, inclinado
const RiseUp: React.FC<{ t: number; at: number; d: number; children: React.ReactNode }> = ({ t, at, d, children }) => {
  const q = kio(t, at, d);
  const top = 100 - q * 125;
  return <AbsoluteFill style={{ clipPath: `polygon(0% ${top + 12}%, 100% ${top}%, 100% 100%, 0% 100%)` }}>{children}</AbsoluteFill>;
};
// 6→7: duas metades se abrem
const Split: React.FC<{ t: number; at: number; d: number; prev: React.ReactNode; next: React.ReactNode }> = ({ t, at, d, prev, next }) => {
  const q = kio(t, at, d);
  return (
    <AbsoluteFill>
      {next}
      <AbsoluteFill style={{ clipPath: "inset(0 0 50% 0)", transform: `translateY(${-q * 52}%)` }}>{prev}</AbsoluteFill>
      <AbsoluteFill style={{ clipPath: "inset(50% 0 0 0)", transform: `translateY(${q * 52}%)` }}>{prev}</AbsoluteFill>
    </AbsoluteFill>
  );
};
// 4→5: o creme sobe de baixo com a borda curva, como líquido
const Fill: React.FC<{ t: number; at: number; d: number; children: React.ReactNode }> = ({ t, at, d, children }) => {
  const q = kio(t, at, d);
  return <AbsoluteFill style={{ clipPath: `ellipse(140% ${q * 130}% at 50% 100%)` }}>{children}</AbsoluteFill>;
};
// 7→8: faixa inclinada atravessa e deixa o vermelho
const Band: React.FC<{ t: number; at: number; d: number; children: React.ReactNode }> = ({ t, at, d, children }) => {
  const q = kio(t, at, d);
  const x = q * 150;
  return <AbsoluteFill style={{ clipPath: `polygon(-60% 0%, ${x}% 0%, ${x - 45}% 100%, -60% 100%)` }}>{children}</AbsoluteFill>;
};

export const Marcos: React.FC = () => {
  const t = toOld(useCurrentFrame() / MA_FPS);
  return (
    <AbsoluteFill style={{ background: RED }}>
      {t < T.s2 + 0.4 && <S1 t={t} />}
      {on(t, T.s2, T.s3 + 0.5) && <Flood t={t} at={T.s2} d={0.42} x={50} y={60}><S2 t={t} /></Flood>}
      {on(t, T.s3, T.s4 + 0.5) && <RiseUp t={t} at={T.s3} d={0.4}><S3 t={t} /></RiseUp>}
      {/* 3→4: a câmera mergulha no sorriso do logo e o branco abre dali */}
      {on(t, T.s4 + 0.05, T.s5 + 0.5) && <Flood t={t} at={T.s4 + 0.05} d={0.4} x={52.6} y={52.3}><S4 t={t} /></Flood>}
      {on(t, T.s5, T.s6 + 0.5) && <Fill t={t} at={T.s5} d={0.4}><S5 t={t} /></Fill>}
      {/* 5→6: o vermelho abre a partir do sorriso de "melhor" */}
      {on(t, T.s6, T.s7) && <Flood t={t} at={T.s6} d={0.45} x={50} y={56.5}><S6 t={t} /></Flood>}
      {on(t, T.s7, T.s7 + 0.4) && <Split t={t} at={T.s7} d={0.4} prev={<S6 t={t} />} next={<S7 t={t} />} />}
      {on(t, T.s7 + 0.4, T.s8 + 0.5) && <S7 t={t} />}
      {on(t, T.s8, 24.2) && <Band t={t} at={T.s8} d={0.45}><S8 t={t} /></Band>}
      {t >= 23.55 && <Flood t={t} at={23.55} d={0.5} x={50} y={53}><S9 t={t} /></Flood>}
    </AbsoluteFill>
  );
};

